// One small JSON per circuit (generated by scripts/build-circuits.mjs), each its own lazy chunk.
const layouts = import.meta.glob("../data/circuits/*.json", { import: "default" });

// Loader for a Jolpica circuitId's layout, or undefined when there is none (mostly pre-1990 venues).
export const circuitLayout = (circuitId) => layouts[`../data/circuits/${circuitId}.json`];
